<!DOCTYPE html>
<html>
<body>
  <button id="toggle">Mostrar</button>
  <p id="msg" style="display:none;">¡Hola mundo!</p>

  <script>
    const btn = document.querySelector('#toggle');
    const msg = document.querySelector('#msg');

    btn.addEventListener('click', () => {
      const visible = msg.style.display === 'none';
      msg.style.display = visible ? 'block' : 'none';
      btn.textContent = visible ? 'Ocultar' : 'Mostrar';
    });
  </script>
</body>
</html>
